// Valida y limpia el payload según el contrato (docs/payload.md, AGNOSTIC-11/13).
// El Webhook entrega el cuerpo en bruto (binario "datos") para poder responder
// 400 también a un JSON mal formado: si n8n lo interpretase, devolvería 422
// antes de ejecutar el flujo y el rechazo no quedaría en logs.
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const TELEFONO = /^\+?[0-9]{9,15}$/;
const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const CANALES = ['whatsapp', 'email'];

const item = $input.first();
const errores = [];
const error = (campo, mensaje) => errores.push({ campo, mensaje });

let cuerpo;
if (!item.binary?.datos) {
  error('body', 'El cuerpo está vacío');
} else {
  const bruto = (await this.helpers.getBinaryDataBuffer(0, 'datos'))
    .toString('utf8')
    .replace(/^﻿/, '');
  try {
    cuerpo = JSON.parse(bruto);
  } catch {
    error('body', 'El cuerpo no es un JSON válido');
  }
}

const datos = {};
let tenantId = null;

if (cuerpo !== undefined) {
  if (cuerpo === null || typeof cuerpo !== 'object' || Array.isArray(cuerpo)) {
    error('body', 'El cuerpo debe ser un objeto JSON');
  } else {
    // Devuelve el texto sin espacios en los extremos, o null si no es válido.
    const texto = (campo, max) => {
      const valor = cuerpo[campo];
      if (valor === undefined || valor === null) {
        error(campo, 'Campo obligatorio');
        return null;
      }
      if (typeof valor !== 'string') {
        error(campo, 'Debe ser un texto');
        return null;
      }
      const limpio = valor.trim();
      if (limpio === '') {
        error(campo, 'Campo obligatorio');
        return null;
      }
      if (max && limpio.length > max) {
        error(campo, `Máximo ${max} caracteres`);
        return null;
      }
      return limpio;
    };

    const tenant = texto('tenant_id');
    if (tenant !== null) {
      if (UUID.test(tenant)) {
        tenantId = tenant.toLowerCase();
      } else {
        error('tenant_id', 'Debe ser un UUID');
      }
    }

    datos.nombre_completo = texto('nombre_completo', 150);

    const dni = texto('dni_nie', 20);
    datos.dni_nie = dni === null ? null : dni.toUpperCase();

    const telefono = texto('telefono');
    if (telefono !== null) {
      const limpio = telefono.replace(/[\s\-()]/g, '');
      if (TELEFONO.test(limpio)) {
        datos.telefono = limpio;
      } else {
        error('telefono', 'Debe tener entre 9 y 15 dígitos, con + opcional al inicio');
      }
    }

    const email = texto('email', 255);
    if (email !== null) {
      if (EMAIL.test(email)) {
        datos.email = email.toLowerCase();
      } else {
        error('email', 'Formato no válido (usuario@dominio.tld)');
      }
    }

    datos.servicio = texto('servicio', 150);

    const canal = texto('canal_preferido');
    if (canal !== null) {
      if (CANALES.includes(canal.toLowerCase())) {
        datos.canal_preferido = canal.toLowerCase();
      } else {
        error('canal_preferido', 'Debe ser "whatsapp" o "email"');
      }
    }

    datos.tenant_id = tenantId;
  }
}

return [{ json: { tenant_id: tenantId, datos, errores } }];

