// Une los errores del payload con la comprobación del tenant, para
// devolverlos todos a la vez en el 400.
const validacion = $('Validar payload').first().json;
const tenantActivo = $input.first().json.tenant_activo === true;

const errores = [...validacion.errores];
if (validacion.tenant_id !== null && !tenantActivo) {
  errores.push({ campo: 'tenant_id', mensaje: 'El tenant no existe o no está activo' });
}

return [{
  json: {
    valido: errores.length === 0,
    errores,
    datos: validacion.datos,
    // Solo se guarda en logs un tenant que exista (FK de logs.tenant_id).
    tenant_id: tenantActivo ? validacion.tenant_id : null,
  },
}];
